// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.recordingimport androidx.room.ColumnInfoimport androidx.room.Daoimport androidx.room.Entityimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.PrimaryKeyimport androidx.room.Queryimport androidx.room.TypeConverterimport timber.log.Timber/** * NOUS — Per-Contact Recording Policy Store (Module 11 v3 — P1). * * Persists [RecordingPolicy] per phone number so the user's preferences * survive process death. Strategy §"CallRecordingEngine": *  - "Per-contact policy (always / never / ask)" → stored here. *  - "30-day auto-expiry" → enforced by [RecordingExpiryWorker]. * * Lives in the same Room DB as the spam numbers ([com.roshan.persona.connectivity.di.ConnectivityDatabase]) * — single passphrase for the whole connectivity stack. */@Entity(tableName = "contact_recording_policy")data class ContactRecordingPolicyEntity(    /**     * Phone number (normalized — digits only, E.164 without `+`).     */    @PrimaryKey    @ColumnInfo(name = "phone_number")    val phoneNumber: String,    @ColumnInfo(name = "policy")    val policy: RecordingPolicy,    @ColumnInfo(name = "updated_at")    val updatedAt: Long = System.currentTimeMillis(),)class RecordingPolicyConverters {    @TypeConverter    fun fromPolicy(policy: RecordingPolicy): String = policy.name    @TypeConverter    fun toPolicy(value: String): RecordingPolicy = RecordingPolicy.fromString(value)}@Daointerface RecordingPolicyDao {    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun upsert(entity: ContactRecordingPolicyEntity)    @Query("SELECT * FROM contact_recording_policy WHERE phone_number = :phoneNumber LIMIT 1")    suspend fun get(phoneNumber: String): ContactRecordingPolicyEntity?    @Query("DELETE FROM contact_recording_policy WHERE phone_number = :phoneNumber")    suspend fun delete(phoneNumber: String): Int    @Query("SELECT * FROM contact_recording_policy")    suspend fun getAll(): List<ContactRecordingPolicyEntity>    @Query("DELETE FROM contact_recording_policy")    suspend fun deleteAll(): Int}/** * Real [RecordingPolicyStore] — wraps the DAO with a friendly API. * * Used by [CallRecordingEngine.startRecording] to decide whether to record * (or ask the user first). */class RecordingPolicyStore(    private val dao: RecordingPolicyDao,) {    /** Get the policy for [phoneNumber], or null if no explicit setting. */    suspend fun get(phoneNumber: String): RecordingPolicy? {        val normalized = phoneNumber.filter { it.isDigit() }        return try {            dao.get(normalized)?.policy        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "get policy failed")            null        }    }    /** Set the policy for [phoneNumber]. */    suspend fun set(phoneNumber: String, policy: RecordingPolicy) {        val normalized = phoneNumber.filter { it.isDigit() }        try {            dao.upsert(                ContactRecordingPolicyEntity(                    phoneNumber = normalized,                    policy = policy,                    updatedAt = System.currentTimeMillis(),                ),            )        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "set policy failed")        }    }    /** Remove the policy for [phoneNumber] (revert to default). */    suspend fun clear(phoneNumber: String) {        val normalized = phoneNumber.filter { it.isDigit() }        try { dao.delete(normalized) } catch (t: Throwable) {            Timber.tag(TAG).e(t, "clear policy failed")        }    }    /** Get all stored policies (for Settings UI). */    suspend fun getAll(): List<ContactRecordingPolicyEntity> = try {        dao.getAll()    } catch (t: Throwable) {        Timber.tag(TAG).e(t, "getAll policies failed")        emptyList()    }    private companion object {        private const val TAG = "RecordingPolicyStore"    }}